exercises.starter:
def count_up(n):
    # yield 0, 1, ..., n - 1 one at a time
    pass

exercises.solution:
def count_up(n):
    for i in range(n):
        yield i

exercises.starter:
def count_down(n):
    # yield n, n - 1, ..., 1 in descending order
    pass

exercises.solution:
def count_down(n):
    for i in range(n, 0, -1):
        yield i

exercises.starter:
def evens_up_to(n):
    # yield 0, 2, 4, ... while they stay below n
    pass

exercises.solution:
def evens_up_to(n):
    for i in range(0, n, 2):
        yield i

exercises.starter:
def take(n, xs):
    # yield the first n elements of xs, then stop
    pass

exercises.solution:
def take(n, xs):
    for i, x in enumerate(xs):
        if i >= n:
            return
        yield x

exercises.starter:
def repeat_each(xs):
    # yield each element of xs twice in a row
    pass

exercises.solution:
def repeat_each(xs):
    for x in xs:
        yield x
        yield x
